"use client"

import * as React from "react"
import { FileText, Layers3, Mail, Paperclip } from "lucide-react"

import { cn } from "@/lib/utils"
import type { ViewerSource } from "@/lib/viewer-source"

import {
  buildMimeTree,
  collectInlineResourceParts,
  findMimeNodeByPath,
  getDefaultMimeSelectionPath,
  getInlineResourceScope,
  getMimeDisplayPart,
  messageIdentity,
  mimePartLabel,
  normalizeContentId,
} from "./email-viewer-model"
import type {
  EmailViewerMessage,
  EmailViewerProps,
  MimeDisplayPart,
  MimePartNode,
  MimePartPath,
} from "./email-viewer-types"
import { formatFileSize } from "./file-size-format"
import { FileThumbnail } from "./file-thumbnail"
import { FileViewer } from "./file-viewer"
import {
  ViewerBody,
  ViewerHeader,
  ViewerRoot,
  ViewerSidebar,
  ViewerSidebarTrigger,
  ViewerSurface,
} from "./viewer"

export type {
  EmailViewerMessage,
  EmailViewerProps,
  MimeDisplayPart,
  MimeHeader,
  MimeMessage,
  MimePart,
  MimePartDisposition,
  MimePartNode,
  MimePartPath,
} from "./email-viewer-types"

export {
  buildMimeTree,
  findMimeNodeByPath,
  getDefaultMimeSelectionPath,
  getInlineResourceScope,
  getMimeDisplayPart,
  replaceCidUrls,
} from "./email-viewer-model"

export interface EmailViewerProviderProps {
  message: EmailViewerMessage
  selectedPath?: MimePartPath | null
  defaultSelectedPath?: MimePartPath
  onSelectedPathChange?: (path: MimePartPath, node: MimePartNode) => void
  children: React.ReactNode
}

type EmailViewerContextValue = {
  display: MimeDisplayPart | null
  message: EmailViewerMessage
  rootNode: MimePartNode
  selectedNode: MimePartNode
  setSelectedNode: (node: MimePartNode) => void
}

const EmailViewerContext = React.createContext<EmailViewerContextValue | null>(
  null
)

export function useEmailViewer() {
  const context = React.useContext(EmailViewerContext)
  if (!context) {
    throw new Error("useEmailViewer must be used within EmailViewerProvider.")
  }
  return context
}

export function useEmailViewerHeader() {
  const { message } = useEmailViewer()
  return { message }
}

export function useEmailViewerPartsList() {
  const { rootNode, selectedNode, setSelectedNode } = useEmailViewer()
  return {
    rootNode,
    selectedPath: selectedNode.path,
    setSelectedNode,
  }
}

export function useEmailViewerSelectedPart() {
  const { display, message, selectedNode } = useEmailViewer()
  return {
    display,
    message,
    selectedNode,
  }
}

export function EmailViewerProvider({
  message,
  selectedPath,
  defaultSelectedPath,
  onSelectedPathChange,
  children,
}: EmailViewerProviderProps) {
  const rootNode = React.useMemo(
    () => buildMimeTree(message.root),
    [message.root]
  )
  const defaultPath = React.useMemo(
    () =>
      defaultSelectedPath && findMimeNodeByPath(rootNode, defaultSelectedPath)
        ? defaultSelectedPath
        : getDefaultMimeSelectionPath(rootNode),
    [defaultSelectedPath, rootNode]
  )
  const [internalSelectedPath, setInternalSelectedPath] =
    React.useState<MimePartPath>(defaultPath)
  const controlled = selectedPath !== undefined
  const activePath = controlled
    ? (selectedPath ?? defaultPath)
    : internalSelectedPath
  const selectedNode =
    findMimeNodeByPath(rootNode, activePath) ??
    findMimeNodeByPath(rootNode, defaultPath) ??
    rootNode

  React.useEffect(() => {
    if (controlled) return
    if (findMimeNodeByPath(rootNode, internalSelectedPath)) return
    setInternalSelectedPath(defaultPath)
  }, [controlled, defaultPath, internalSelectedPath, rootNode])

  const setSelectedNode = React.useCallback(
    (node: MimePartNode) => {
      if (!controlled) setInternalSelectedPath(node.path)
      onSelectedPathChange?.(node.path, node)
    },
    [controlled, onSelectedPathChange]
  )
  const inlineResourceUrls = useInlineMimeResourceUrls(
    getInlineResourceScope(selectedNode)
  )
  const display = React.useMemo(
    () => getMimeDisplayPart(selectedNode, inlineResourceUrls),
    [inlineResourceUrls, selectedNode]
  )
  const value = React.useMemo<EmailViewerContextValue>(
    () => ({
      display,
      message,
      rootNode,
      selectedNode,
      setSelectedNode,
    }),
    [display, message, rootNode, selectedNode, setSelectedNode]
  )

  return (
    <EmailViewerContext.Provider value={value}>
      {children}
    </EmailViewerContext.Provider>
  )
}

export function EmailViewer({
  message,
  selectedPath,
  defaultSelectedPath,
  onSelectedPathChange,
  className,
  bare = false,
}: EmailViewerProps) {
  return (
    <EmailViewerProvider
      message={message}
      selectedPath={selectedPath}
      defaultSelectedPath={defaultSelectedPath}
      onSelectedPathChange={onSelectedPathChange}
    >
      <div data-slot="email-viewer" className={cn("min-h-0", className)}>
        <ViewerRoot bare={bare} defaultSidebarOpen className="h-full">
          <EmailViewerHeader />
          <ViewerBody className="flex-col md:flex-row">
            <ViewerSurface className="min-h-[26rem] md:min-h-0">
              <EmailViewerSelectedPart />
            </ViewerSurface>
            <ViewerSidebar
              aria-label="Email parts"
              side="right"
              width="19rem"
              className="border-t md:border-t-0 md:border-l"
            >
              <EmailViewerPartsList />
            </ViewerSidebar>
          </ViewerBody>
        </ViewerRoot>
      </div>
    </EmailViewerProvider>
  )
}

export function EmailViewerHeader() {
  const { message } = useEmailViewerHeader()
  return <MimeMessageHeader message={message} />
}

export function EmailViewerPartsList() {
  const { rootNode, selectedPath, setSelectedNode } = useEmailViewerPartsList()
  return (
    <MimePartSidebar
      root={rootNode}
      selectedPath={selectedPath}
      onSelectNode={setSelectedNode}
    />
  )
}

export function EmailViewerSelectedPart() {
  const { display, message, selectedNode } = useEmailViewerSelectedPart()
  return (
    <MimeViewerContent
      message={message}
      selectedNode={selectedNode}
      display={display}
    />
  )
}

function MimeViewerContent({
  message,
  selectedNode,
  display,
}: {
  message: EmailViewerMessage
  selectedNode: MimePartNode
  display: MimeDisplayPart | null
}) {
  if (selectedNode.isMessage && selectedNode.children.length > 0) {
    return (
      <EmailViewer
        bare
        className="h-full"
        message={{
          id: `${messageIdentity(message)}:${selectedNode.part.id}`,
          headers: selectedNode.part.headers,
          subject: headerValue(selectedNode.part.headers, "subject"),
          from: headerValue(selectedNode.part.headers, "from"),
          to: headerValue(selectedNode.part.headers, "to"),
          sentAt: headerValue(selectedNode.part.headers, "date"),
          root: selectedNode.part,
        }}
      />
    )
  }

  if (!display) {
    return (
      <div className="flex size-full items-center justify-center px-6 text-center text-sm text-muted-foreground">
        This MIME part does not have a previewable body.
      </div>
    )
  }

  return (
    <FileViewer
      key={display.node.path.join("/")}
      source={display.source}
      as={display.category}
      bare
      className="size-full min-h-0"
    />
  )
}

function MimeMessageHeader({ message }: { message: EmailViewerMessage }) {
  const subject = message.subject?.trim() || "(no subject)"
  const recipients = normalizeAddressList(message.to)
  const sentAt = formatSentAt(message.sentAt)

  return (
    <ViewerHeader className="px-3 py-2">
      <div
        data-slot="email-message-header"
        className="flex min-h-0 flex-col gap-1"
      >
        <div className="flex min-w-0 items-center gap-2">
          <Mail className="size-4 flex-shrink-0 text-muted-foreground" />
          <h2 className="min-w-0 flex-1 truncate text-sm font-medium">
            {subject}
          </h2>
          <ViewerSidebarTrigger className="-mr-1" />
        </div>
        <div className="flex min-w-0 flex-wrap gap-x-3 gap-y-1 pl-6 text-xs text-muted-foreground">
          {message.from ? (
            <span className="min-w-0 truncate">From {message.from}</span>
          ) : null}
          {recipients ? (
            <span className="min-w-0 truncate">To {recipients}</span>
          ) : null}
          {sentAt ? <span className="tabular-nums">{sentAt}</span> : null}
        </div>
      </div>
    </ViewerHeader>
  )
}

function MimePartSidebar({
  root,
  selectedPath,
  onSelectNode,
  className,
}: {
  root: MimePartNode
  selectedPath: MimePartPath
  onSelectNode: (node: MimePartNode) => void
  className?: string
}) {
  const { bodyNodes, attachmentNodes } = React.useMemo(
    () => getSidebarSections(root),
    [root]
  )
  const partCount = bodyNodes.length + attachmentNodes.length

  return (
    <div
      data-slot="mime-part-sidebar"
      className={cn(
        "flex h-full min-h-0 flex-col bg-background text-foreground",
        className
      )}
    >
      <div className="flex-shrink-0 border-b px-3 py-2">
        <div className="flex h-6 items-center gap-2 text-xs font-medium">
          <Paperclip className="size-3.5 text-muted-foreground" />
          <span>
            {partCount} item{partCount === 1 ? "" : "s"}
          </span>
        </div>
      </div>
      <div className="min-h-0 flex-1 space-y-2 overflow-auto p-2">
        <MimePartSidebarSection title="Body">
          <ul className="flex flex-col gap-1">
            {bodyNodes.map((node) => (
              <MimePartSidebarItem
                key={node.path.join("/")}
                label="Body"
                node={node}
                selectedPath={selectedPath}
                onSelectNode={onSelectNode}
              />
            ))}
          </ul>
        </MimePartSidebarSection>
        <MimePartSidebarSection title="Attachments">
          {attachmentNodes.length === 0 ? (
            <p className="px-2 py-3 text-xs text-muted-foreground">
              No attachments.
            </p>
          ) : (
            <ul className="flex flex-col gap-1">
              {attachmentNodes.map((node) => (
                <MimePartSidebarItem
                  key={node.path.join("/")}
                  node={node}
                  selectedPath={selectedPath}
                  onSelectNode={onSelectNode}
                />
              ))}
            </ul>
          )}
        </MimePartSidebarSection>
      </div>
    </div>
  )
}

function MimePartSidebarSection({
  title,
  children,
}: {
  title: string
  children: React.ReactNode
}) {
  const titleId = React.useId()

  return (
    <section
      aria-labelledby={titleId}
      data-slot="mime-part-sidebar-section"
      className="min-w-0"
    >
      <h3
        id={titleId}
        className="flex h-8 shrink-0 items-center px-2 text-xs font-medium text-muted-foreground"
      >
        {title}
      </h3>
      {children}
    </section>
  )
}

function getSidebarSections(root: MimePartNode): {
  bodyNodes: MimePartNode[]
  attachmentNodes: MimePartNode[]
} {
  const attachmentNodes: MimePartNode[] = []

  walkCurrentMessageNodes(root, (node) => {
    if (node.isMultipart) return
    if (node.isInlineResource) return
    if (node.isAttachment || node.isMessage) {
      attachmentNodes.push(node)
      return
    }
  })

  const bodyNode = getBodyNode(root)
  const bodyNodes = bodyNode ? [bodyNode] : [root]
  return { attachmentNodes, bodyNodes }
}

function getBodyNode(root: MimePartNode) {
  const candidates: MimePartNode[] = []

  walkCurrentMessageNodes(root, (node) => {
    if (!node.isRenderable) return
    if (node.isInlineResource || node.isAttachment || node.isMessage) return
    candidates.push(node)
  })

  return (
    candidates.find(
      (node) => normalizedMimeType(node.part.mimeType) === "text/html"
    ) ??
    candidates.find(
      (node) => normalizedMimeType(node.part.mimeType) === "text/plain"
    ) ??
    candidates[0] ??
    null
  )
}

function MimePartSidebarItem({
  label,
  node,
  selectedPath,
  onSelectNode,
}: {
  label?: string
  node: MimePartNode
  selectedPath: MimePartPath
  onSelectNode: (node: MimePartNode) => void
}) {
  const isSelected = pathsEqual(node.path, selectedPath)
  const canRenderThumbnail = Boolean(node.part.source && !node.isInlineResource)
  const meta = sidebarMeta(node)
  const title = label ?? mimePartLabel(node.part)

  return (
    <li data-slot="mime-part-sidebar-item">
      <button
        type="button"
        aria-current={isSelected ? "page" : undefined}
        aria-label={`${title} ${meta}`}
        data-selected={isSelected ? "true" : "false"}
        className={cn(
          "flex h-auto w-full items-center gap-3 overflow-hidden rounded-lg border p-2 text-left text-sm outline-hidden transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring active:bg-accent",
          isSelected
            ? "border-border bg-accent text-accent-foreground"
            : "border-transparent"
        )}
        onClick={() => onSelectNode(node)}
      >
        {canRenderThumbnail && node.part.source ? (
          <FileThumbnail
            source={node.part.source}
            presentation="decorative"
            className="size-12 flex-shrink-0"
            previewAspectRatio={1}
          />
        ) : (
          <span
            className={cn(
              "flex size-12 flex-shrink-0 items-center justify-center rounded-md bg-muted/60",
              isSelected ? "text-accent-foreground" : "text-muted-foreground"
            )}
          >
            <PartIcon node={node} className="size-4" />
          </span>
        )}
        <span className="flex min-w-0 flex-1 flex-col gap-1">
          <span className="truncate text-sm font-medium">{title}</span>
          <span
            className={cn(
              "truncate text-xs",
              isSelected ? "text-accent-foreground/80" : "text-muted-foreground"
            )}
          >
            {meta}
          </span>
        </span>
      </button>
    </li>
  )
}

function PartIcon({
  node,
  className,
}: {
  node: MimePartNode
  className?: string
}) {
  if (node.isMultipart || node.isMessage) {
    return <Layers3 className={className} aria-hidden />
  }
  if (node.isAttachment) {
    return <Paperclip className={className} aria-hidden />
  }
  return <FileText className={className} aria-hidden />
}

function useInlineMimeResourceUrls(node: MimePartNode) {
  const inlineParts = React.useMemo(
    () => collectInlineResourceParts(node),
    [node]
  )
  const [urls, setUrls] = React.useState<ReadonlyMap<string, string>>(
    () => new Map()
  )

  React.useEffect(() => {
    const nextUrls = new Map<string, string>()
    const objectUrls: string[] = []

    for (const inlinePart of inlineParts) {
      const cid = normalizeContentId(inlinePart.part.contentId)
      const source = inlinePart.part.source
      if (!cid || !source) continue

      const url = sourceToInlineUrl(source, objectUrls)
      if (url) nextUrls.set(cid, url)
    }

    setUrls(nextUrls)

    return () => {
      for (const url of objectUrls) URL.revokeObjectURL(url)
    }
  }, [inlineParts])

  return urls
}

function sourceToInlineUrl(source: ViewerSource, objectUrls: string[]) {
  if (source.kind === "url") return source.url
  if (source.kind === "blob") {
    const url = URL.createObjectURL(source.blob)
    objectUrls.push(url)
    return url
  }

  return textSourceToDataUrl(source.text, source.mimeType)
}

function textSourceToDataUrl(text: string, mimeType: string | undefined) {
  const bytes = new TextEncoder().encode(text)
  const chunkSize = 0x8000
  let binary = ""
  for (let index = 0; index < bytes.length; index += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(index, index + chunkSize))
  }
  return `data:${mimeType ?? "text/plain;charset=utf-8"};base64,${btoa(binary)}`
}

function sidebarMeta(node: MimePartNode) {
  if (node.part.size != null) {
    return `${node.part.mimeType} · ${formatFileSize(node.part.size)}`
  }
  if (node.isInlineResource) return `${node.part.mimeType} · inline`
  if (node.isAttachment) return `${node.part.mimeType} · attachment`
  return node.part.mimeType
}

function walkMimeNodes(
  node: MimePartNode,
  visit: (node: MimePartNode) => void
) {
  visit(node)
  for (const child of node.children) walkMimeNodes(child, visit)
}

function walkCurrentMessageNodes(
  root: MimePartNode,
  visit: (node: MimePartNode) => void
) {
  function walk(node: MimePartNode) {
    visit(node)
    if (node !== root && node.isMessage) return
    for (const child of node.children) walk(child)
  }

  walk(root)
}

function pathsEqual(left: MimePartPath, right: MimePartPath) {
  if (left.length !== right.length) return false
  return left.every((part, index) => part === right[index])
}

function normalizedMimeType(mimeType: string) {
  return mimeType.toLowerCase().split(";")[0].trim()
}

function normalizeAddressList(
  value: string | readonly string[] | null | undefined
) {
  if (typeof value === "string") return value.trim() || null
  if (value) return value.filter(Boolean).join(", ")
  return null
}

function formatSentAt(value: string | Date | null | undefined) {
  if (!value) return null
  const date = value instanceof Date ? value : new Date(value)
  if (Number.isNaN(date.getTime())) return null
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date)
}

function headerValue(
  headers: readonly { name: string; value: string }[] | undefined,
  name: string
) {
  return (
    headers?.find((header) => header.name.toLowerCase() === name.toLowerCase())
      ?.value ?? null
  )
}

"use client"

import * as React from "react"
import { PanelLeft, PanelRight } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button, type ButtonProps } from "@/components/ui/button"

export type ViewerRootProps = React.ComponentProps<"div"> & {
  bare?: boolean
  defaultSidebarOpen?: boolean
  sidebarOpen?: boolean
  onSidebarOpenChange?: (open: boolean) => void
  sidebarMode?: ViewerSidebarRequestedMode
  sidebarInlineBreakpoint?: number
}

export type ViewerSidebarMode = "inline" | "overlay"
export type ViewerSidebarRequestedMode = "auto" | ViewerSidebarMode
export type ViewerSidebarState = "expanded" | "collapsed"
export type ViewerSidebarContextValue = {
  state: ViewerSidebarState
  open: boolean
  setOpen: (value: boolean | ((open: boolean) => boolean)) => void
  toggleSidebar: () => void
  canToggleSidebar: boolean
  mode: ViewerSidebarMode
  sidebarId: string
}

type ViewerSidebarSide = "left" | "right"
type ViewerSidebarCollapsible = "offcanvas" | "none"
type ViewerSidebarRegistration = {
  collapsible: ViewerSidebarCollapsible
  element: HTMLElement
  id: string
  instanceId: string
  side: ViewerSidebarSide
  width: string
}

type ViewerSidebarRegistrationContextValue = {
  hasSidebar: boolean
  sidebarState: ViewerSidebarContextValue
  registerSidebar: (registration: ViewerSidebarRegistration) => () => void
  rootId: string
  sidebarSide: ViewerSidebarSide
  setLastTriggerElement: (element: HTMLElement | null) => void
}

const VIEWER_SIDEBAR_INLINE_BREAKPOINT = 768
const VIEWER_SIDEBAR_MODE_HYSTERESIS = 16
const VIEWER_SIDEBAR_WIDTH = "10rem"

const ViewerSidebarStateContext =
  React.createContext<ViewerSidebarContextValue | null>(null)
const ViewerSidebarRegistrationContext =
  React.createContext<ViewerSidebarRegistrationContextValue | null>(null)

function resolveSidebarMode({
  requestedMode,
  width,
  inlineBreakpoint,
}: {
  requestedMode: ViewerSidebarRequestedMode
  width: number | null
  inlineBreakpoint: number
}): ViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode
  if (width === null) return "overlay"
  return width >= inlineBreakpoint ? "inline" : "overlay"
}

function resolveMeasuredSidebarMode({
  currentMode,
  hasMeasured,
  inlineBreakpoint,
  requestedMode,
  width,
}: {
  currentMode: ViewerSidebarMode
  hasMeasured: boolean
  inlineBreakpoint: number
  requestedMode: ViewerSidebarRequestedMode
  width: number
}): ViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode
  if (!hasMeasured) {
    return width >= inlineBreakpoint ? "inline" : "overlay"
  }

  if (currentMode === "inline") {
    return width < inlineBreakpoint - VIEWER_SIDEBAR_MODE_HYSTERESIS
      ? "overlay"
      : "inline"
  }

  return width > inlineBreakpoint + VIEWER_SIDEBAR_MODE_HYSTERESIS
    ? "inline"
    : "overlay"
}

function useIsoLayoutEffect(
  effect: React.EffectCallback,
  deps: React.DependencyList
) {
  const useEffect =
    typeof window === "undefined" ? React.useEffect : React.useLayoutEffect
  useEffect(effect, deps)
}

function isAriaDisabled(value: unknown): boolean {
  return value === true || value === "true"
}

export function useViewerSidebar(): ViewerSidebarContextValue {
  const context = React.useContext(ViewerSidebarStateContext)
  if (!context) {
    throw new Error("useViewerSidebar must be used within a ViewerRoot.")
  }
  return context
}

export function useOptionalViewerSidebar(): ViewerSidebarContextValue | null {
  return React.useContext(ViewerSidebarStateContext)
}

function useViewerSidebarRegistrationContext(
  consumer: string
): ViewerSidebarRegistrationContextValue {
  const context = React.useContext(ViewerSidebarRegistrationContext)
  if (!context) {
    throw new Error(`${consumer} must be used within a ViewerRoot.`)
  }
  return context
}

export function ViewerRoot({
  bare = false,
  className,
  style,
  defaultSidebarOpen = false,
  sidebarOpen: sidebarOpenProp,
  onSidebarOpenChange,
  sidebarMode = "auto",
  sidebarInlineBreakpoint = VIEWER_SIDEBAR_INLINE_BREAKPOINT,
  ...props
}: ViewerRootProps) {
  const rootRef = React.useRef<HTMLDivElement | null>(null)
  const reactId = React.useId()
  const rootId = `${reactId}-viewer-root`
  const fallbackSidebarId = `${reactId}-viewer-sidebar`
  const isControlled = sidebarOpenProp !== undefined
  const [internalOpen, setInternalOpen] = React.useState(defaultSidebarOpen)
  const open = sidebarOpenProp ?? internalOpen
  const openRef = React.useRef(open)
  const hasMeasuredSidebarWidthRef = React.useRef(false)
  const lastTriggerElementRef = React.useRef<HTMLElement | null>(null)
  const registeredSidebarRef = React.useRef<ViewerSidebarRegistration | null>(
    null
  )
  const [registeredSidebar, setRegisteredSidebar] =
    React.useState<ViewerSidebarRegistration | null>(null)
  const [resolvedSidebarMode, setResolvedSidebarMode] =
    React.useState<ViewerSidebarMode>(() =>
      resolveSidebarMode({
        requestedMode: sidebarMode,
        width: null,
        inlineBreakpoint: sidebarInlineBreakpoint,
      })
    )

  React.useEffect(() => {
    openRef.current = open
  }, [open])

  React.useEffect(() => {
    if (sidebarMode === "auto") return
    setResolvedSidebarMode((currentMode) => {
      const nextMode = sidebarMode
      return currentMode === nextMode ? currentMode : nextMode
    })
  }, [sidebarMode])

  useIsoLayoutEffect(() => {
    const element = rootRef.current
    const ResizeObserverConstructor = globalThis.ResizeObserver
    if (!element || typeof ResizeObserverConstructor === "undefined") return
    if (sidebarMode !== "auto") {
      setResolvedSidebarMode(sidebarMode)
      return
    }

    const updateMode = () => {
      const nextWidth = element.getBoundingClientRect().width
      if (nextWidth === 0) return

      setResolvedSidebarMode((currentMode) => {
        const nextMode = resolveMeasuredSidebarMode({
          currentMode,
          hasMeasured: hasMeasuredSidebarWidthRef.current,
          requestedMode: sidebarMode,
          width: nextWidth,
          inlineBreakpoint: sidebarInlineBreakpoint,
        })

        hasMeasuredSidebarWidthRef.current = true
        return currentMode === nextMode ? currentMode : nextMode
      })
    }

    updateMode()

    const observer = new ResizeObserverConstructor(updateMode)
    observer.observe(element)

    return () => observer.disconnect()
  }, [sidebarInlineBreakpoint, sidebarMode])

  const setOpen = React.useCallback(
    (value: boolean | ((open: boolean) => boolean)) => {
      const previousOpen = isControlled ? open : openRef.current
      const nextOpen = typeof value === "function" ? value(previousOpen) : value

      if (nextOpen === previousOpen) {
        return
      }

      if (!isControlled) {
        openRef.current = nextOpen
        setInternalOpen(nextOpen)
      }
      onSidebarOpenChange?.(nextOpen)
    },
    [isControlled, onSidebarOpenChange, open]
  )

  const registerSidebar = React.useCallback(
    (registration: ViewerSidebarRegistration) => {
      const currentRegistration = registeredSidebarRef.current

      if (
        currentRegistration &&
        currentRegistration.instanceId !== registration.instanceId
      ) {
        throw new Error(
          "ViewerRoot supports one primary ViewerSidebar. Use a nested ViewerRoot for a complete nested viewer, or put secondary content inside ViewerSurface."
        )
      }

      registeredSidebarRef.current = registration
      setRegisteredSidebar(registration)

      return () => {
        if (
          registeredSidebarRef.current?.instanceId !== registration.instanceId
        ) {
          return
        }

        registeredSidebarRef.current = null
        setRegisteredSidebar(null)
      }
    },
    []
  )

  const toggleSidebar = React.useCallback(() => {
    setOpen((currentOpen) => !currentOpen)
  }, [setOpen])

  const hasSidebar = registeredSidebar !== null
  const effectiveOpen = registeredSidebar?.collapsible === "none" ? true : open
  const state: ViewerSidebarState = effectiveOpen ? "expanded" : "collapsed"
  const canToggleSidebar =
    hasSidebar && registeredSidebar.collapsible !== "none"
  const sidebarId = registeredSidebar?.id ?? fallbackSidebarId
  const sidebarSide = registeredSidebar?.side ?? "left"
  const sidebarWidth = registeredSidebar?.width ?? VIEWER_SIDEBAR_WIDTH
  const setLastTriggerElement = React.useCallback(
    (element: HTMLElement | null) => {
      lastTriggerElementRef.current = element
    },
    []
  )

  React.useEffect(() => {
    if (
      !open ||
      !canToggleSidebar ||
      resolvedSidebarMode !== "overlay" ||
      typeof document === "undefined"
    ) {
      return
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false)
        const triggerElement =
          lastTriggerElementRef.current?.isConnected === true
            ? lastTriggerElementRef.current
            : rootRef.current?.querySelector<HTMLElement>(
                "[data-viewer-sidebar-trigger]"
              )
        triggerElement?.focus()
      }
    }
    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target

      if (
        target instanceof Node &&
        registeredSidebar?.element.contains(target)
      ) {
        return
      }

      if (target instanceof Element) {
        const triggerElement = target.closest<HTMLElement>(
          "[data-viewer-sidebar-trigger]"
        )
        if (triggerElement?.dataset.viewerRootId === rootId) {
          return
        }
      }

      setOpen(false)
    }

    document.addEventListener("keydown", handleKeyDown)
    document.addEventListener("pointerdown", handlePointerDown)

    return () => {
      document.removeEventListener("keydown", handleKeyDown)
      document.removeEventListener("pointerdown", handlePointerDown)
    }
  }, [
    canToggleSidebar,
    open,
    registeredSidebar,
    resolvedSidebarMode,
    rootId,
    setOpen,
  ])

  const sidebarStateContext = React.useMemo<ViewerSidebarContextValue>(
    () => ({
      state,
      open: effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      mode: resolvedSidebarMode,
      sidebarId,
    }),
    [
      state,
      effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      resolvedSidebarMode,
      sidebarId,
    ]
  )

  const sidebarRegistrationContext =
    React.useMemo<ViewerSidebarRegistrationContextValue>(
      () => ({
        hasSidebar,
        sidebarState: sidebarStateContext,
        registerSidebar,
        rootId,
        sidebarSide,
        setLastTriggerElement,
      }),
      [
        hasSidebar,
        sidebarStateContext,
        registerSidebar,
        rootId,
        sidebarSide,
        setLastTriggerElement,
      ]
    )

  return (
    <ViewerSidebarStateContext.Provider value={sidebarStateContext}>
      <ViewerSidebarRegistrationContext.Provider
        value={sidebarRegistrationContext}
      >
        <div
          ref={rootRef}
          data-slot="viewer-root"
          data-viewer-root-id={rootId}
          className={cn(
            "relative flex min-h-0 flex-col overflow-hidden",
            bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
            className
          )}
          style={
            {
              ...style,
              "--viewer-sidebar-width": sidebarWidth,
            } as React.CSSProperties
          }
          {...props}
        />
      </ViewerSidebarRegistrationContext.Provider>
    </ViewerSidebarStateContext.Provider>
  )
}

